-- The layout each role opens on.
--
-- Dashboards resolved user, then global, then the shipped default. There was
-- no role step, so every new account landed on the same fourteen widgets
-- whatever job it did. DashboardTemplate::getRoleDashboard now fills that gap
-- and reads what this migration writes.
--
-- Both layouts are built only from widgets that already exist. What changes is
-- the order and what is left out.
--
-- The ISP opens on device reachability and the event list, then links and
-- poller health in a second row. No ONT optical anywhere on it -- 943 of the
-- 993 open events are subscriber optical, so putting them here would bury the
-- 50 that are the ISP's own work.
--
-- The reseller opens on their subscribers, then the two things they act on
-- today: the worst optical readings and the ONTs waiting to be activated.
--
-- Stored in the role's params column, a JSON field that was already there and
-- empty. Re-running is safe -- it overwrites with the same content.

UPDATE user_roles
SET params = JSON_SET(COALESCE(params, JSON_OBJECT()), '$.dashboard_template', CAST('{"lg":[{"x":0,"y":0,"w":12,"h":12,"i":1,"widget":"pinger_stat","moved":false},{"x":12,"y":0,"w":12,"h":12,"i":2,"widget":"device_status_chart","moved":false},{"x":0,"y":12,"w":14,"h":26,"i":3,"widget":"events_table","moved":false},{"x":14,"y":12,"w":10,"h":26,"i":4,"widget":"events_stat","moved":false},{"x":0,"y":38,"w":8,"h":14,"i":5,"widget":"high_link_utilization","moved":false},{"x":8,"y":38,"w":8,"h":14,"i":6,"widget":"events_stat_by_name","moved":false},{"x":16,"y":38,"w":8,"h":14,"i":7,"widget":"device_calling_errors_stat","moved":false},{"x":0,"y":52,"w":24,"h":11,"i":8,"widget":"system_stat","moved":false}],"md":[{"x":0,"y":0,"w":6,"h":12,"i":1,"widget":"pinger_stat","moved":false},{"x":6,"y":0,"w":6,"h":12,"i":2,"widget":"device_status_chart","moved":false},{"x":0,"y":12,"w":7,"h":26,"i":3,"widget":"events_table","moved":false},{"x":7,"y":12,"w":5,"h":26,"i":4,"widget":"events_stat","moved":false},{"x":0,"y":38,"w":4,"h":14,"i":5,"widget":"high_link_utilization","moved":false},{"x":4,"y":38,"w":4,"h":14,"i":6,"widget":"events_stat_by_name","moved":false},{"x":8,"y":38,"w":4,"h":14,"i":7,"widget":"device_calling_errors_stat","moved":false},{"x":0,"y":52,"w":12,"h":11,"i":8,"widget":"system_stat","moved":false}],"sm":[{"x":0,"y":0,"w":8,"h":12,"i":1,"widget":"pinger_stat","moved":false},{"x":0,"y":12,"w":8,"h":12,"i":2,"widget":"device_status_chart","moved":false},{"x":0,"y":24,"w":8,"h":26,"i":3,"widget":"events_table","moved":false},{"x":0,"y":50,"w":8,"h":26,"i":4,"widget":"events_stat","moved":false},{"x":0,"y":76,"w":8,"h":14,"i":5,"widget":"high_link_utilization","moved":false},{"x":0,"y":90,"w":8,"h":14,"i":6,"widget":"events_stat_by_name","moved":false},{"x":0,"y":104,"w":8,"h":14,"i":7,"widget":"device_calling_errors_stat","moved":false},{"x":0,"y":118,"w":8,"h":11,"i":8,"widget":"system_stat","moved":false}],"xs":[{"x":0,"y":0,"w":6,"h":12,"i":1,"widget":"pinger_st